                  <i class="bi bi-person-fill text-white" style="font-size: 0.75rem;"></i>
                </div>
                <span class="small fw-bold text-success">Admin</span>
                <button @click="handleLogout" class="btn btn-sm btn-link p-0 text-danger text-decoration-none ms-1" title="Sign Out">
