          <p class="text-muted small mb-4">Scanning multi-exchange order books in real-time...</p>
          
          <!-- Exchange Status Badges -->
          <div class="d-flex justify-content-center gap-3 mb-4 flex-wrap">
            <div class="exchange-badge d-flex align-items-center gap-2 px-3 py-1 rounded-pill border">
              <span class="pulse-dot binance"></span>
              <span class="small fw-bold">Binance</span>
            </div>
            <div class="exchange-badge d-flex align-items-center gap-2 px-3 py-1 rounded-pill border">
              <span class="pulse-dot paribu"></span>
              <span class="small fw-bold">Paribu</span>
            </div>
            <div class="exchange-badge d-flex align-items-center gap-2 px-3 py-1 rounded-pill border">
              <span class="pulse-dot btcturk"></span>
              <span class="small fw-bold">BtcTurk</span>
            </div>
          </div>

          <!-- Progress Shimmer Bar -->
          <div class="loading-progress-bar rounded-pill mx-auto">
            <div class="loading-shimmer"></div>
          </div>
          <div class="mt-2 text-muted" style="font-size: 0.72rem; letter-spacing: 1px; text-transform: uppercase;">Analyzing Liquidity & Arbitrage Spreads</div>
        </div>
      </div>

      <div class="row mt-0" v-if="Object.keys(coinData).length>0">
         
         <!-- Display Top Deals Based on API settings Limit -->
         <div class="d-flex align-items-center mb-1 mt-0">
            <i class="bi bi-fire text-danger me-2"></i>
            <span class="small fw-bold section-label text-uppercase" style="letter-spacing:1px; font-size: 0.75rem;">Top Deals</span>
            <!-- Sort Toggle: Gain vs ROI -->
            <div class="btn-group btn-group-sm ms-2" role="group">
               <button type="button" class="btn btn-sm py-0 px-2 fw-bold" :class="topDealsSortBy === 'gain' ? 'btn-success text-white' : 'btn-outline-secondary'" @click="setTopDealsSortBy('gain')" style="font-size: 0.68rem;" title="Sort Top Deals by Potential Gain">
                 <i class="bi bi-cash-stack me-1"></i>Gain
               </button>
               <button type="button" class="btn btn-sm py-0 px-2 fw-bold" :class="topDealsSortBy === 'roi' ? 'btn-primary text-white' : 'btn-outline-secondary'" @click="setTopDealsSortBy('roi')" style="font-size: 0.68rem;" title="Sort Top Deals by ROI %">
                 <i class="bi bi-percent me-1"></i>ROI
               </button>
            </div>
            <hr class="flex-grow-1 ms-2 my-0 section-hr">
            <div class="d-flex align-items-center ms-2 gap-1 theme-text" style="font-size: 0.75rem;">
               <button type="button" class="btn btn-sm btn-link p-0 text-decoration-none theme-text fw-bold" @click="changeFontSize('topDeals', -1)"><i class="bi bi-dash fs-5"></i></button>
               <span class="mx-1"><i class="bi bi-fonts fs-6"></i></span>
               <button type="button" class="btn btn-sm btn-link p-0 text-decoration-none theme-text fw-bold" @click="changeFontSize('topDeals', 1)"><i class="bi bi-plus fs-5"></i></button>
            </div>
         </div>
         <div class="d-flex flex-wrap align-items-start mb-1">
            <coinbox
                v-for="deal in topDealsList"
                :key="'top_'+deal.coin"
                :coinName="deal.coin"
                :coinData="coinData[deal.coin]"
                :USDTMode="USDTMode"
                :forceShowROI="true"
                :isTopDeal="true"
                :dealDuration="topDealTimers[deal.coin] || 0"
                :customFontSize="topDealsFontSize"
            />
            <div v-if="topDealsList.length === 0" class="p-3 text-muted small fst-italic w-100">
              <i class="bi bi-radar me-1 text-primary"></i>Scanning markets for active cross-exchange arbitrage spreads...
            </div>
         </div>
         
         <!-- Display Remaining Coins Alphabetically -->
         <div class="d-flex align-items-center mb-1 mt-1">
            <i class="bi bi-coin text-warning me-2"></i>
            <span class="small fw-bold section-label text-uppercase" style="letter-spacing:1px; font-size: 0.75rem;">All Markets</span>
            <hr class="flex-grow-1 ms-2 my-0 section-hr">
            <div class="d-flex align-items-center ms-2 gap-1 theme-text" style="font-size: 0.75rem;">
               <button type="button" class="btn btn-sm btn-link p-0 text-decoration-none theme-text fw-bold" @click="changeFontSize('allMarkets', -1)"><i class="bi bi-dash fs-5"></i></button>
               <span class="mx-1"><i class="bi bi-fonts fs-6"></i></span>
               <button type="button" class="btn btn-sm btn-link p-0 text-decoration-none theme-text fw-bold" @click="changeFontSize('allMarkets', 1)"><i class="bi bi-plus fs-5"></i></button>
            </div>
         </div>
         <div class="d-flex flex-wrap align-items-start pb-3">
            <coinbox
                v-for="coinName in sortedRemainingCoins"
                :key="'list_'+coinName"
                :coinName="coinName"
                :coinData="coinData[coinName]"
                :USDTMode="USDTMode"
                :minROI="settings.crossMinROI"
                :isTopDeal="false"
                :dealDuration="0"
                :customFontSize="allMarketsFontSize"
            />
         </div>
         
      </div>
    
      <!-- Profit Calculator Modal Backdrop Overlay -->
      <div v-if="showCalculatorModal" class="modal-backdrop-custom d-flex justify-content-center align-items-center" @click.self="showCalculatorModal = false">
        <div class="modal-wrapper p-4 rounded-4 shadow-lg border" style="width: 380px; max-width: 90vw; position: relative; background-color: var(--current-card-bg, #ffffff); opacity: 1;">
          <button class="btn btn-sm btn-outline-secondary position-absolute top-0 end-0 m-3 border-0 rounded-circle" @click="showCalculatorModal = false">
            <i class="bi bi-x-lg"></i>
          </button>
          
          <div class="text-center mb-4">
             <i class="bi bi-calculator-fill fs-2 text-primary mb-2"></i>
             <h5 class="fw-bold theme-text mb-0">Profit Calculator</h5>
             <p class="small text-muted mb-0">Live estimation tool</p>
          </div>
          
          <div class="p-3 border rounded-3 bg-light-soft theme-input-minimal shadow-sm">
            <div class="theme-text-secondary">
              <div class="mb-3 p-3 rounded bg-dark-soft text-center fw-bold text-success border border-success-subtle fs-4 bg-opacity-25 shadow-inner">
                $ {{typeof coinData !== "undefined" ? formatNumber((coinData[selectedCoin]?.binance?.usdt?.price-buyPrice)*buyAmount,2) : '0.00'}}
              </div>
              
              <label class="form-label small fw-bold mb-1 mt-2 text-uppercase text-muted">Select Asset</label>
              <Select2 v-model="selectedCoin" :options="coinList" :settings="{ placeholder: selectedCoin }" @change="myChangeEvent($event)" @select="mySelectEvent($event)" />
              
              <div class="mt-3 text-start">
                <label class="form-label small fw-bold mb-1 text-uppercase text-muted">Buy Order Target (Price)</label>
                <input type="number" class="form-control form-control-lg theme-input-minimal font-monospace" v-model="buyPrice" placeholder="0.0000">
              </div>
              
              <div class="mt-3 text-start">
                <label class="form-label small fw-bold mb-1 text-uppercase text-muted">Position Size (Amount)</label>
                <input type="number" class="form-control form-control-lg theme-input-minimal font-monospace" v-model="buyAmount" placeholder="100.0">
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- Admin Login Modal -->
      <div v-if="showLoginModal" class="modal-backdrop-custom d-flex justify-content-center align-items-center" @click.self="showLoginModal = false">
        <div class="modal-wrapper p-4 rounded-4 shadow-lg border" style="width: 360px; max-width: 90vw; position: relative; background-color: var(--current-card-bg, #ffffff);">
          <button class="btn btn-sm btn-outline-secondary position-absolute top-0 end-0 m-3 border-0 rounded-circle" @click="showLoginModal = false">
            <i class="bi bi-x-lg"></i>
          </button>
          
          <div class="text-center mb-4">
             <i class="bi bi-shield-lock-fill fs-2 text-primary mb-2"></i>
             <h5 class="fw-bold theme-text mb-0">Operator Authentication</h5>
             <p class="small text-muted mb-0">Unlock live arbitrage engine & orderbooks</p>
          </div>

          <div v-if="loginError" class="alert alert-danger py-2 small mb-3">
            {{ loginError }}
          </div>

          <form @submit.prevent="submitLogin">
            <div class="mb-3 text-start">
              <label class="form-label small fw-bold text-uppercase text-muted">Username</label>
              <input type="text" v-model="loginForm.username" class="form-control form-control-lg theme-input-minimal" placeholder="admin" required>
            </div>
            <div class="mb-3 text-start">
              <label class="form-label small fw-bold text-uppercase text-muted">Password</label>
              <input type="password" v-model="loginForm.password" class="form-control form-control-lg theme-input-minimal" placeholder="••••••••" required>
            </div>
            <button type="submit" class="btn btn-primary w-100 rounded-pill py-2 fw-bold" :disabled="loginLoading">
              {{ loginLoading ? 'Authenticating...' : 'Sign In' }}
            </button>
          </form>
        </div>
      </div>
    </div>
  </template>
  <script>
  import { defineComponent } from 'vue';
  import coinBox from '../components/coinBox';
  import topCoin from '../components/topCoin';
  import axios from 'axios';
  import { APP_VERSION } from '@/version';

  export default defineComponent({
    name: 'VueCoinDashboard',
    components: {
      coinbox: coinBox,
      topcoin: topCoin,
    },
    data() {
      return {
        appVersion: APP_VERSION,
        isDemoMode: typeof window !== 'undefined' && (window.location.hostname.includes('github.io') || window.location.search.includes('demo=1')),
        demoRecordedAt: '',
        demoFrames: [],
        currentFrameIndex: 0,
        demoInterval: null,
        filterWord: '',
        coinData: {},
        coinData2: [],
        topCoins: ['btc','bnb','ftt','usdt','jup','sevilla','eth','shib'],
        topDealsCount: 10,
        topDealsSortBy: localStorage.getItem('vuecoin_topDealsSortBy') || 'gain',
        topDealTimers: {},
        topDealEntryTimes: JSON.parse(localStorage.getItem('vuecoin_topDealEntryTimes')) || {},
        crossMinROI: 0.5,
        coinList : [],
        enabled: true,
        selectedCoin: 'btc',
        buyPrice: null,
        buyAmount: null,
        showCalculatorModal: false,
        showLoginModal: false,
        loginLoading: false,
        loginError: '',
        loginForm: {
          username: '',
          password: ''
        },
        USDTMode: localStorage.getItem('vuecoin_usdt_mode') !== null ? localStorage.getItem('vuecoin_usdt_mode') === 'true' : true,
        dragging: false,
        elapsedTime: 0,
        timer: undefined,
        socket: null,
        mobileMenuOpen: false,
        saving: false,
        topDealsFontSize: parseFloat(localStorage.getItem('vuecoin_topDealsFontSize')) || 0.72,
        allMarketsFontSize: parseFloat(localStorage.getItem('vuecoin_allMarketsFontSize')) || 0.75,
        settings: {
           topDealsCount: 10,
           crossMinROI: 0.5,
           crossMinProfit: 1000,
           crossEnabled: true,
           intraEnabled: true,
           intraMinROI: 0,
           intraMinProfit: 100,
           blockedCoins: []
        },
        portfolio: [],
        showBalance: localStorage.getItem('vuecoin_showBalance') !== 'false',
        currentProfile: null,
     }
    },
    filters: {
      lira (value) {
        return `$${Number(value).toLocaleString('en-US')}`
      },
      ROI (value) {
        return `$${Number(value).toLocaleString('en-US', { minimumFractionDigits: 4 })}`
      }
    },
    computed: {
      isAdminAuthenticated() {
        return this.$store?.state?.isAuthenticated || false;
      }
    },
    methods: {
      openLoginModal() {
        this.loginError = '';
        this.showLoginModal = true;
      },
      async submitLogin() {
        this.loginLoading = true;
        this.loginError = '';
        try {
          await this.$store.dispatch('login', {
            username: this.loginForm.username.trim(),
            password: this.loginForm.password
          });
          this.showLoginModal = false;
        } catch (err) {
          this.loginError = err.message || 'Giriş başarısız oldu.';
        } finally {
          this.loginLoading = false;
        }
      },
      async handleLogout() {
        await this.$store.dispatch('logout');
      },
      async fetchSettings() {
        try {
          const response = await axios.get('/api/settings');
          if (response.data) {
            this.settings = { ...this.settings, ...response.data };
            if (response.data.topCoins) this.topCoins = response.data.topCoins;
            if (response.data.topDealsCount !== undefined) this.topDealsCount = response.data.topDealsCount;
            if (response.data.crossMinROI !== undefined) this.crossMinROI = response.data.crossMinROI;
            if (this.$store) {
              this.$store.commit('SET_SETTINGS', response.data);
            }
            if (this.coinData && Object.keys(this.coinData).length > 0) {
              this.processData(this.coinData);
            }
          }
        } catch (error) {
          console.error("Failed to fetch settings:", error);
        }
      },
      async saveSettings() {
        this.saving = true;
        try {
          await axios.post('/api/settings', this.settings);
          this.topDealsCount = parseInt(this.settings.topDealsCount);
        } catch (error) {
           console.error('Failed to save settings:', error);
        } finally {
           this.saving = false;
        }
      },
        loadPortfolio() {
            const stored = localStorage.getItem('vuecoin_portfolio');
            if (stored) {
                try {
                    this.portfolio = JSON.parse(stored);
                } catch (e) {
                    this.portfolio = [];
                }
            }

            // Always pick some assets if empty or if we want it fresh (randomized for demo)
            // If the user hasn't explicitly added something, we refresh it for the demo
            if (this.isDemoMode && !localStorage.getItem('vuecoin_user_manually_edited')) {
                this.randomizeDemoAssets();
            }
            
            this.currentProfile = localStorage.getItem('vuecoin_current_profile') || null;
        },
        randomizeDemoAssets() {
            if (!this.coinData || Object.keys(this.coinData).length === 0) return;
            
            const keys = Object.keys(this.coinData);
            const numAssets = 4 + Math.floor(Math.random() * 3);
            const selected = [];
            
            // Filter out metadata keys
            const validKeys = [...keys].filter(k => k !== 'ROI' && k !== 'recordedAt' && k !== 'frames');
            const tempKeys = validKeys.sort(() => 0.5 - Math.random());
            
            for (let i = 0; i < Math.min(numAssets, tempKeys.length); i++) {
                const coin = tempKeys[i];
                const currentPrice = this.getCurrentPrice(coin);
                if (currentPrice === 0) continue;
                
                // Realistic amount based on price (approx $1000 - $5000 investment)
                const targetValue = 1000 + Math.random() * 4000;
                const amount = targetValue / currentPrice;
                
                selected.push({
                    coin: coin,
                    amount: amount,
                    avgPrice: currentPrice * (0.95 + Math.random() * 0.1)
                });
            }
            this.portfolio = selected;
        },
      exitProfile() {
        this.currentProfile = null;
        localStorage.setItem('vuecoin_current_profile', '');
        this.loadPortfolio();
      },
      getCurrentPrice(coin) {
         if (!coin) return 0;
         if (coin === 'usdt') return 1;
         if (this.coinData[coin]) {
           if (this.coinData[coin].binance?.usdt?.price) return this.coinData[coin].binance.usdt.price;
           if (this.coinData[coin].paribu?.usdt?.price) return this.coinData[coin].paribu.usdt.price;
           if (this.coinData[coin].paribu?.try?.price && this.USDTMode) {
              const rate = this.coinData['usdt']?.paribu?.try?.price || 35;
              return this.coinData[coin].paribu.try.price / rate;
           }
         }
         return 0;
      },
      formatNumber(value, forceFraction = null) {
        const val = parseFloat(value);
        if (isNaN(val)) return "0";
        
        if (forceFraction !== null && !isNaN(parseInt(forceFraction))) {
            const f = parseInt(forceFraction);
            return val.toLocaleString('en-US', { 
              minimumFractionDigits: f, 
              maximumFractionDigits: f 
            });
        }

        let maxF = 4;
        const absVal = Math.abs(val);

        if (absVal >= 1000) maxF = 0; // e.g. 1450
        else if (absVal >= 100) maxF = 1; // e.g. 123.4
        else if (absVal >= 10) maxF = 2; // e.g. 12.34
        else if (absVal >= 1) maxF = 3;  // e.g. 1.234
        else if (absVal >= 0.1) maxF = 4; // e.g. 0.1234
        else if (absVal >= 0.01) maxF = 5; // e.g. 0.01234
        else if (absVal >= 0.001) maxF = 6;
        else if (absVal >= 0.0001) maxF = 7;
        else maxF = 8;

        return val.toLocaleString('en-US', { 
          minimumFractionDigits: 0, 
          maximumFractionDigits: maxF
        });
      },
      log(event) {
        console.log(event)
      },
      getIcon(coinName) {
        if (!coinName) return require(`@/assets/coins/noimage.png`);
        try {
          return require(`@/assets/coins/${coinName.toLowerCase()}.png`);
        } catch (e) {
          return require(`@/assets/coins/noimage.png`);
        }
      },
      increaseTopCoin (){
        this.topCoinAmount++
      },
      decreaseTopCoin (){
        this.topCoinAmount--
      },
      myChangeEvent(val){
        console.log(val);
      },
      mySelectEvent({id}){
        console.log('Selected:', id);
        if (this.coinData[id] && this.coinData[id].binance?.usdt?.price) {
          this.buyPrice = this.coinData[id].binance.usdt.price;
        }
      },
      setTopDealsSortBy(mode) {
        this.topDealsSortBy = mode;
        localStorage.setItem('vuecoin_topDealsSortBy', mode);
        if (this.coinData && Object.keys(this.coinData).length > 0) {
          this.processData(this.coinData);
        }
      },
      processData(data) {
          if (!data || typeof data !== 'object') return;
          this.coinData = data;
          this.reset();
          
          let coinList = [];
          Object.keys(data).forEach(coinName => {
              coinList.push(coinName);
          });
          this.coinList = coinList;
      },
      async updateData() {
        try {
            const response = await axios.get('/api/allParibuData');
            this.processData(response.data);
        } catch (error) {
            console.log(error);
        }
      },

      incrementTopDeals() {
        if (this.topDealsCount < 50) {
          this.topDealsCount++;
          this.settings.topDealsCount = this.topDealsCount;
          this.saveSettings();
        }
      },
      decrementTopDeals() {
        if (this.topDealsCount > 1) {
          this.topDealsCount--;
          this.settings.topDealsCount = this.topDealsCount;
          this.saveSettings();
        }
      },
      changeFontSize(type, step) {
        if (type === 'topDeals') {
          this.topDealsFontSize = Math.max(0.4, Math.min(1.5, this.topDealsFontSize + (step * 0.05)));
          localStorage.setItem('vuecoin_topDealsFontSize', this.topDealsFontSize);
        } else if (type === 'allMarkets') {
          this.allMarketsFontSize = Math.max(0.4, Math.min(1.5, this.allMarketsFontSize + (step * 0.05)));
          localStorage.setItem('vuecoin_allMarketsFontSize', this.allMarketsFontSize);
        }
      },
      cellClass(coinROI) {
        if (!coinROI || coinROI < 0.2) return 'theme-text-secondary';
        if (coinROI < 1.0) return 'text-success fw-bold';
        if (coinROI < 3.0) return 'text-warning fw-bold';
        return 'text-danger fw-bold';
      },
      start() {
        this.timer = setInterval(() => {
          this.elapsedTime += 1000;
        }, 1000);
      },
      stop() {
        clearInterval(this.timer);
      },
      reset() {
        this.elapsedTime = 0;
      },
      filteredBySearch(arr, filterWord) {
        return Object.keys(arr).filter(coin => coin.includes(filterWord.toLowerCase()))
      },
      async fetchMockData() {
          try {
              // Ensure we load from the base path properly
              const response = await axios.get('./mockData.json');
              if (response.data && response.data.frames) {
                  this.demoRecordedAt = response.data.recordedAt || 'Unknown Date';
                  this.demoFrames = response.data.frames;
                  this.currentFrameIndex = 0;
                  this.coinData = this.demoFrames[this.currentFrameIndex];
                  
                  // Seed random assets immediately if demo mode and not manually edited
                  if (this.isDemoMode && !localStorage.getItem('vuecoin_user_manually_edited')) {
                      this.randomizeDemoAssets();
                  }
                  
                  // Cycle frames every 2.5 seconds
                  this.demoInterval = setInterval(() => {
                      this.currentFrameIndex = (this.currentFrameIndex + 1) % this.demoFrames.length;
                      this.processData(this.demoFrames[this.currentFrameIndex]);
                  }, 2500);
              }
          } catch (error) {
              console.error("Failed to load mock data:", error);
          }
      }
    },
    created() {
      this.start();
      
      if (this.isDemoMode) {
          this.fetchMockData();
      } else {
          // Instantly render from global store if data already exists
          if (this.$store.state.coinData && (this.$store.state.coinData.btc || Object.keys(this.$store.state.coinData).length > 5)) {
              this.processData(this.$store.state.coinData);
          } else {
              this.updateData();
          }
      }
      
      // Fetch user settings
      this.fetchSettings();
      this.loadPortfolio();
    },
    activated() {
      // Re-fetch settings and re-process deals when returning to cached Dashboard
      this.fetchSettings();
      this.loadPortfolio();
      if (this.coinData && Object.keys(this.coinData).length > 0) {
        this.processData(this.coinData);
      }
    },
    watch: {
      '$store.state.coinData': {
        handler(newData) {
          if (!this.isDemoMode && newData && (newData.btc || Object.keys(newData).length > 5)) {
            this.processData(newData);
          }
        },
        deep: true,
        immediate: true
      },
      topDealsList: {
        handler(newDeals) {
          if (!newDeals) return;
          const now = Date.now();
          const activeKeys = newDeals.map(d => d.coin);
          activeKeys.forEach(coin => {
            if (!this.topDealEntryTimes[coin]) {
              this.topDealEntryTimes[coin] = now;
            }
          });
          Object.keys(this.topDealEntryTimes).forEach(coin => {
            if (!activeKeys.includes(coin)) {
              delete this.topDealEntryTimes[coin];
            }
          });
          try {
            localStorage.setItem('vuecoin_topDealEntryTimes', JSON.stringify(this.topDealEntryTimes));
          } catch (e) {}

          const timers = {};
          activeKeys.forEach(coin => {
            timers[coin] = Math.round((now - (this.topDealEntryTimes[coin] || now)) / 1000);
          });
          this.topDealTimers = timers;
        },
        deep: true,
        immediate: true
      },
      '$store.state.settings': {
        handler(newSettings) {
          if (newSettings && Object.keys(newSettings).length > 0) {
            this.settings = { ...this.settings, ...newSettings };
            if (newSettings.topDealsCount !== undefined) {
              this.topDealsCount = newSettings.topDealsCount;
            }
            if (newSettings.topCoins) {
              this.topCoins = newSettings.topCoins;
            }
            if (newSettings.crossMinROI !== undefined) {
              this.crossMinROI = newSettings.crossMinROI;
            }
            if (this.coinData && Object.keys(this.coinData).length > 0) {
              this.processData(this.coinData);
            }
          }
        },
        deep: true
      },
      USDTMode(newVal) {
        localStorage.setItem('vuecoin_usdt_mode', newVal);
      },
      selectedCoin(newVal) {
        if (this.coinData[newVal] && this.coinData[newVal].binance?.usdt?.price) {
          this.buyPrice = this.coinData[newVal].binance.usdt.price;
        }
      },
      showBalance(newVal) {
         localStorage.setItem('vuecoin_showBalance', newVal);
      }
    },
    beforeUnmount() {
      this.stop();
      if (this.demoInterval) {
          clearInterval(this.demoInterval);
      }
    },
    computed: {
      totalBalanceUsdt() {
         return this.portfolio.reduce((sum, item) => {
            return sum + (item.amount * this.getCurrentPrice(item.coin));
         }, 0);
      },
      totalBalanceTry() {
         const rate = this.coinData['usdt']?.paribu?.try?.price || 35;
         return this.totalBalanceUsdt * rate;
      },
      formattedElapsedTime() {
        const date = new Date(null);
        date.setSeconds(this.elapsedTime / 1000);
        const utc = date.toUTCString();
        return utc.substr(utc.indexOf(":") - 2, 8);
      },
      calculatedUsdtRate() {
         // Priority: Binance TRY -> Paribu TRY -> Default 36.5
         if (this.coinData && this.coinData['usdt']) {
             if (this.coinData['usdt'].binance && this.coinData['usdt'].binance.try && this.coinData['usdt'].binance.try.price) {
                 return this.coinData['usdt'].binance.try.price;
             }
             if (this.coinData['usdt'].paribu && this.coinData['usdt'].paribu.try && this.coinData['usdt'].paribu.try.price) {
                 return this.coinData['usdt'].paribu.try.price;
             }
         }
         return 36.5; // Fallback
      },
      topDealsList() {
        if (!this.coinData || typeof this.coinData !== 'object' || Object.keys(this.coinData).length === 0) return [];
        const s = this.settings || {};
        const blockedCoins = Array.isArray(s.blockedCoins) ? s.blockedCoins.map(c => String(c).toLowerCase().trim()) : [];
        const validDeals = [];

        Object.keys(this.coinData).forEach(coinName => {
          if (coinName === 'usdt' || coinName === 'ROI' || coinName === 'recordedAt' || coinName === 'frames') return;
          const cleanCoin = coinName.toLowerCase().trim();
          if (blockedCoins.includes(cleanCoin)) return;

          const d = this.coinData[coinName];
          if (!d || typeof d !== 'object') return;

          const r = (typeof d.ROI === 'number' && !isNaN(d.ROI)) ? d.ROI : -999;
          let gain = 0;
          if (d.arbitrageDetails) {
            const crossP = d.arbitrageDetails.cross?.profit || 0;
            const intraP = d.arbitrageDetails.intra?.profit || 0;
            gain = Math.max(crossP, intraP);
          }
          if (gain <= 0 && d.profit > 0) gain = d.profit;
          if (gain <= 0 && r > 0 && this.isDemoMode) {
            const pseudoSeed = (coinName || 'btc').split('').reduce((acc, c) => acc + c.charCodeAt(0), 0);
            const mockVolume = 8000 + ((pseudoSeed * 491) % 32000);
            gain = (mockVolume * r) / 100;
          }

          let marketCount = 0;
          if (d.paribu?.try?.price > 0 || d.paribu?.usdt?.price > 0) marketCount++;
          if (d.binance?.usdt?.price > 0 || d.binance?.try?.price > 0) marketCount++;
          if (d.BTCTurk?.try?.price > 0 || d.BTCTurk?.usdt?.price > 0) marketCount++;

          const hasCross = d.arbitrageDetails?.cross && (d.arbitrageDetails.cross.roi > 0 || d.arbitrageDetails.cross.profit > 0);
          const hasIntra = d.arbitrageDetails?.intra && (d.arbitrageDetails.intra.roi > 0 || d.arbitrageDetails.intra.profit > 0);
          const hasGenericArb = (marketCount >= 2 && r > 0) || (marketCount >= 2 && gain > 0);

          if (hasCross || hasIntra || hasGenericArb || (r > 0 && (d.arbitrageDetails?.cross || d.arbitrageDetails?.intra))) {
            const bestRoi = Math.max(r, d.arbitrageDetails?.cross?.roi || -999, d.arbitrageDetails?.intra?.roi || -999);
            validDeals.push({
              coin: coinName,
              roi: bestRoi > -900 ? bestRoi : (r > 0 ? r : 0),
              gain: gain
            });
          }
        });

        if (this.topDealsSortBy === 'roi') {
          validDeals.sort((a, b) => b.roi !== a.roi ? b.roi - a.roi : b.gain - a.gain);
        } else {
          validDeals.sort((a, b) => b.gain !== a.gain ? b.gain - a.gain : b.roi - a.roi);
        }

        const count = parseInt(this.topDealsCount) || 10;
        return validDeals.slice(0, count);
      },
      topDeals() {
        const map = {};
        this.topDealsList.forEach(d => {
          map[d.coin] = d.roi;
        });
        return map;
      },
      sortedRemainingCoins() {
         // Show ALL coins (including top deals) sorted alphabetically
         const remaining = Object.keys(this.coinData).filter(coin => {
            if (coin === 'usdt') return false;
            const d = this.coinData[coin];
            if (!d) return false;
            const hasActiveData = (d.paribu?.try?.price > 0) || (d.binance?.usdt?.price > 0) || (d.BTCTurk?.try?.price > 0);
            return hasActiveData;
         });
         return remaining.sort((a,b) => a.localeCompare(b));
      }
    }
  })
  </script>


